import re
from typing import Dict, List, Any, Tuple, Optional

# ------------------------------------------------------------------
# Helper functions (already given, just restated for completeness)
# ------------------------------------------------------------------
def node_by_title(doc: Dict, title: str) -> Optional[Dict]:
    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None


def node_by_id(doc: Dict, node_id: str) -> Optional[Dict]:
    for n in doc.get("nodes", []):
        if n.get("node_id") == node_id:
            return n
    return None


def children(doc: Dict, node: Dict) -> List[Dict]:
    return [node_by_id(doc, cid) for cid in node.get("children", []) if node_by_id(doc, cid) is not None]


def scope_nodes(doc: Dict, scope: Dict) -> List[Dict]:
    """Return all child nodes of a scope node."""
    return children(doc, scope)


def table_rows(node: Dict) -> List[Tuple[int, Dict[str, str]]]:
    """Return (row_index, row_dict) for a table node."""
    cols = node["table"]["columns"]
    rows = []
    for i, r in enumerate(node["table"]["rows"]):
        rows.append((i, dict(zip(cols, r))))
    return rows


# ------------------------------------------------------------------
# Utilities
# ------------------------------------------------------------------
def _int(x: Any) -> Optional[int]:
    try:
        return int(x)
    except Exception:
        return None


# ------------------------------------------------------------------
# Public API
# ------------------------------------------------------------------
def entities(doc: Dict, scope: str) -> List[Dict[str, str]]:
    """List distinct product entities in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Prefer the Products table
    prod_node = node_by_title(doc, f"{scope}: Products")
    rows_iter = []
    if prod_node:
        rows_iter = table_rows(prod_node)
    else:
        # fallback: any ledger row that contains a product column
        ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
        if ledger_node:
            rows_iter = table_rows(ledger_node)

    ents: List[Dict[str, str]] = []
    seen = set()
    for _, row in rows_iter:
        pid = row.get("product") or row.get("product code")
        if pid and pid not in seen:
            seen.add(pid)
            ents.append({"id": pid, "description": pid})
    return ents


def recorded_end(doc: Dict, scope: str) -> Optional[int]:
    """Return the last day number in the Daily ledger."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if not ledger_node:
        return None
    max_day: Optional[int] = None
    for _, row in table_rows(ledger_node):
        d = _int(row.get("day"))
        if d is not None:
            max_day = d if max_day is None or d > max_day else max_day
    return max_day


def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """List all external inputs to the process."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    res: List[Dict[str, Any]] = []

    # 1. Opening stock (from Products table)
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for r_idx, row in table_rows(prod_node):
            pid = row.get("product")
            opening = _int(row.get("opening stock"))
            if pid and opening is not None:
                res.append({
                    "id": f"open_stock_{pid}",
                    "time": None,
                    "kind": "opening_stock",
                    "entities": [pid],
                    "fields": {"opening_stock": opening},
                    "src": [[prod_node["node_id"], r_idx, ["product", "opening stock"]]]
                })

    # 2. Production and daily sales orders (from Daily ledger)
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for r_idx, row in table_rows(ledger_node):
            day = _int(row.get("day"))
            pid = row.get("product")
            produced = _int(row.get("produced"))
            ordered = _int(row.get("ordered"))
            if day is None or not pid:
                continue
            if produced is not None:
                res.append({
                    "id": f"prod_{pid}_d{day}",
                    "time": day,
                    "kind": "production",
                    "entities": [pid],
                    "fields": {"produced": produced},
                    "src": [[ledger_node["node_id"], r_idx, ["day", "product", "produced"]]]
                })
            if ordered is not None:
                res.append({
                    "id": f"ord_{pid}_d{day}",
                    "time": day,
                    "kind": "sales_order",
                    "entities": [pid],
                    "fields": {"ordered": ordered},
                    "src": [[ledger_node["node_id"], r_idx, ["day", "product", "ordered"]]]
                })

    # 3. Planned production & orders (from Order book tables)
    for child in children(doc, scope_node):
        if child.get("kind") != "table":
            continue
        title = child.get("title", "")
        if "Order book: Orders received and production planned" in title:
            for r_idx, row in table_rows(child):
                day = _int(row.get("day"))
                pid = row.get("product")
                planned_prod = _int(row.get("planned production"))
                planned_ord = _int(row.get("ordered"))
                if day is None or not pid:
                    continue
                if planned_prod is not None:
                    res.append({
                        "id": f"plan_prod_{pid}_d{day}",
                        "time": day,
                        "kind": "planned_production",
                        "entities": [pid],
                        "fields": {"planned_production": planned_prod},
                        "src": [[child["node_id"], r_idx, ["day", "product", "planned production"]]]
                    })
                if planned_ord is not None:
                    res.append({
                        "id": f"plan_ord_{pid}_d{day}",
                        "time": day,
                        "kind": "planned_order",
                        "entities": [pid],
                        "fields": {"planned_order": planned_ord},
                        "src": [[child["node_id"], r_idx, ["day", "product", "ordered"]]]
                    })
    return res


def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """List all outcomes produced by the process."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    res: List[Dict[str, Any]] = []

    # 1. Daily ledger reported state changes
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for r_idx, row in table_rows(ledger_node):
            day = _int(row.get("day"))
            pid = row.get("product")
            if day is None or not pid:
                continue
            shipped = _int(row.get("shipped"))
            backordered = _int(row.get("backordered"))
            stock = _int(row.get("stock"))
            if shipped is not None:
                res.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [pid],
                    "value": shipped,
                    "src": [[ledger_node["node_id"], r_idx, ["day", "product", "shipped"]]]
                })
            if backordered is not None:
                res.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [pid],
                    "value": backordered,
                    "src": [[ledger_node["node_id"], r_idx, ["day", "product", "backordered"]]]
                })
            if stock is not None:
                res.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [pid],
                    "value": stock,
                    "src": [[ledger_node["node_id"], r_idx, ["day", "product", "stock"]]]
                })

    # 2. Event lines
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node:
        prod_ids = {e["id"] for e in entities(doc, scope)}
        lines = ev_node.get("lines", [])
        for l_idx, line in enumerate(lines):
            # extract day number
            m = re.search(r"Day\s+(\d+)", line)
            day = int(m.group(1)) if m else None
            # determine event kind
            low = line.lower()
            if "dispatch capacity reached" in low:
                kind = "capacity_reached"
            elif "runs out of stock" in low:
                kind = "stock_run_out"
            elif "fully backordered" in low:
                kind = "order_fully_backordered"
            elif "backlog cleared" in low:
                kind = "backlog_cleared"
            elif "shipped in full" in low:
                kind = "order_shipped_in_full"
            else:
                kind = "event"
            # entities involved
            involved = [pid for pid in prod_ids if pid in line]
            res.append({
                "time": day,
                "kind": kind,
                "entities": involved,
                "value": None,
                "src": [[ev_node["node_id"], l_idx]]
            })

    return res


def params(doc: Dict, scope: str) -> Dict[str, Any]:
    """Return constants declared in this scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    out: Dict[str, Any] = {}

    # plant id from title
    m = re.search(r"Plant\s+(\d+)", scope)
    if m:
        out["plant_id"] = int(m.group(1))

    # capacity from the Plant title text node
    cap = None
    # Find the text node that is the scope itself
    if scope_node.get("kind") == "text":
        txt = scope_node.get("text", "")
        mm = re.search(r"Daily dispatch capacity:\s*([\d,]+)\s*kg", txt)
        if mm:
            cap = int(mm.group(1).replace(",", ""))
    # Fallback: check event lines for a capacity value
    if cap is None:
        ev_node = node_by_title(doc, f"{scope}: Events")
        if ev_node:
            for line in ev_node.get("lines", []):
                mm = re.search(r"\(([\d,.]+)\s+of\s+[\d,.]+ kg\)", line)
                if mm:
                    num = mm.group(1).replace(".", "").replace(",", "")
                    try:
                        cap = int(num)
                        break
                    except Exception:
                        continue
    if cap is not None:
        out["daily_dispatch_capacity"] = cap

    return out


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward simulation of Plant 2103 dispatch logic.

    Parameters
    ----------
    doc : dict
        Document dictionary (only needed for product weights).
    scope : str
        Title of the scope to simulate
        (example: 'Plant 2103, Period 15').
    inputs : list[dict]
        List of input records returned by ``inputs(doc, scope)``.
    params : dict
        Dictionary of parameters for the plant (plant_id,
        daily_dispatch_capacity, …).
    start : int | None
        First day to emit outcome records.
        If ``None`` the earliest day present in the inputs is used.
    horizon : int | None
        Last day to emit outcome records.
        If ``None`` the latest day present in the inputs is used.

    Returns
    -------
    list[dict]
        Outcome records in the same format as returned by
        ``outcomes(doc, scope)``.
    """
    # ------------------------------------------------------------------
    # 1. Parse input records
    # ------------------------------------------------------------------
    def add(target, day, pid, qty):
        """utility: add qty to target[day][pid]"""
        target.setdefault(day, {}).setdefault(pid, 0)
        target[day][pid] += qty

    opening = {}
    prod_by_day = {}
    ord_by_day = {}

    for r in inputs:
        k = r["kind"]
        if k == "opening_stock":
            pid = r["entities"][0]
            opening[pid] = r["fields"]["opening_stock"]
        elif k in ("production", "planned_production"):
            day, pid = r["time"], r["entities"][0]
            add(prod_by_day, day, pid, r["fields"].get("produced", 0))
        elif k in ("sales_order", "planned_order"):
            day, pid = r["time"], r["entities"][0]
            add(ord_by_day, day, pid, r["fields"].get("ordered", 0))

    # ------------------------------------------------------------------
    # 2. Build weight lookup (kg per unit) from Products table
    # ------------------------------------------------------------------
    prod_node = node_by_title(doc, f"{scope}: Products")
    weights = {}
    if prod_node:
        for _, row in table_rows(prod_node):
            weights[row["product"]] = float(row["kg per unit"])
    else:
        weights = {pid: 1.0 for pid in opening}  # Fallback

    # Unique product list
    all_prods = set(opening.keys())

    # ------------------------------------------------------------------
    # 3. Simulation bounds
    # ------------------------------------------------------------------
    all_days = set(prod_by_day.keys()) | set(ord_by_day.keys())
    if not all_days:
        return []

    earliest_day = min(all_days)
    latest_day = max(all_days)

    start_day = int(start) if start is not None else earliest_day
    end_day   = int(horizon) if horizon is not None else latest_day

    # ------------------------------------------------------------------
    # 4. Initialise state
    # ------------------------------------------------------------------
    stock = {pid: opening.get(pid, 0) for pid in all_prods}
    open_orders: list[dict] = []   # each: {"pid", "remaining", "day_placed"}

    capacity = params.get("daily_dispatch_capacity", 0)

    def total_backordered(pid):
        return sum(o["remaining"] for o in open_orders if o["pid"] == pid)

    # ------------------------------------------------------------------
    # 5. Main simulation loop
    # ------------------------------------------------------------------
    outcomes = []

    for day in range(earliest_day, end_day + 1):
        # 5.1 Production
        for pid, qty in prod_by_day.get(day, {}).items():
            stock[pid] = stock.get(pid, 0) + qty

        # 5.2 New orders
        for pid, qty in ord_by_day.get(day, {}).items():
            if qty > 0:
                open_orders.append({"pid": pid, "remaining": qty, "day_placed": day})

        # 5.3 Dispatch
        used_cap = 0.0
        # Order priority: oldest first; same day: lower remaining qty, then pid
        open_orders.sort(key=lambda o: (o["day_placed"], o["remaining"], o["pid"]))
        shipped_today = {pid: 0 for pid in all_prods}

        for o in list(open_orders):          # copy to allow mutation
            if used_cap >= capacity:
                break
            pid = o["pid"]
            w = weights.get(pid, 1.0)
            avail_cap = capacity - used_cap
            max_units_by_cap = int(avail_cap // w) if w > 0 else 0
            ship_qty = min(o["remaining"],
                           max_units_by_cap,
                           stock.get(pid, 0))
            if ship_qty <= 0:
                continue
            # execute ship
            o["remaining"] -= ship_qty
            stock[pid] -= ship_qty
            used_cap += ship_qty * w
            shipped_today[pid] += ship_qty
            if o["remaining"] == 0:
                open_orders.remove(o)

        # 5.4 Emit outcomes for days >= start_day
        if day >= start_day:
            for pid in sorted(all_prods):
                outcomes.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [pid],
                    "value": shipped_today.get(pid, 0)
                })
                outcomes.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [pid],
                    "value": total_backordered(pid)
                })
                outcomes.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [pid],
                    "value": stock.get(pid, 0)
                })

    return outcomes

