import re

# ------------------------------------------------------------------
# Helpers (assume already defined in the sandbox)
# ------------------------------------------------------------------
# node_by_title(doc, title) -> node or None
# node_by_id(doc, node_id) -> node
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> list of child nodes within scope
# table_rows(node) -> list of (row_index, {col: cell}) for table nodes

# ------------------------------------------------------------------
# Local helper functions
# ------------------------------------------------------------------
def _find_nodes(doc, parent, pattern):
    """Return nodes under parent whose title matches pattern (regex)."""
    return [n for n in children(doc, parent) if re.search(pattern, n['title'])]

def _parse_int(val):
    try:
        return int(val)
    except:
        return None

def _parse_float(val):
    try:
        return float(val)
    except:
        return None

# ------------------------------------------------------------------
