def entities(doc, scope):
    """Return list of entities in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Find the Products table
    prod_nodes = _find_nodes(doc, scope_node, r'em\s+Products$')
    res = []
    if prod_nodes:
        prod_node = prod_nodes[0]
        rows = table_rows(prod_node)
        for idx, row in rows:
            p = row['product']
            res.append({"id": p, "description": p})
    else:
        # fallback: gather from ledger
        ledger_nodes = _find_nodes(doc, scope_node, r'em\s+Daily ledger$')
        if ledger_nodes:
            ledger_node = ledger_nodes[0]
            rows = table_rows(ledger_node)
            seen = set()
            for idx, row in rows:
                p = row['product']
                if p not in seen:
                    seen.add(p)
                    res.append({"id": p, "description": p})
    return res

def recorded_end(doc, scope):
    """Return last time point covered by the scope's records."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    ledger_nodes = _find_nodes(doc, scope_node, r'em\s+Daily ledger$')
    if not ledger_nodes:
        return None
    ledger_node = ledger_nodes[0]
    max_day = None
    for idx, row in table_rows(ledger_node):
        d = _parse_int(row['day'])
        if d is not None:
            if max_day is None or d > max_day:
                max_day = d
    return max_day

def inputs(doc, scope):
