                    "id": f"plan_prod_{prod_id}_d{day}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [prod_id],
                    "fields": {"planned_production": prod_planned},
                    "src": [[ob_node['node_id'], idx, ["day", "product", "planned production"]]],
                })
            if ord_planned is not None:
                inputs_list.append({
