                    "time": day,
                    "kind": "planned_order",
                    "entities": [prod_id],
                    "fields": {"planned_order": ord_planned},
                    "src": [[ob_node['node_id'], idx, ["day", "product", "ordered"]]],
                })

    return inputs_list

def outcomes(doc, scope):
    """Return all outcomes for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    outcomes_list = []

    # Ledger outcomes: shipped, backordered, stock
    ledger_nodes = _find_nodes(doc, scope_node, r'em\s+Daily ledger$')
    if ledger_nodes:
