        for idx, row in table_rows(ledger_node):
            day = _parse_int(row['day'])
            prod_id = row['product']
            shipped = _parse_int(row['shipped'])
            backordered = _parse_int(row['backordered'])
            stock = _parse_int(row['stock'])
            if shipped is not None:
                outcomes_list.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [prod_id],
                    "value": shipped,
                    "src": [[ledger_node['node_id'], idx, ["day", "product", "shipped"]]],
                })
            if backordered is not None:
                outcomes_list.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [prod_id],
                    "value": backordered,
                    "src": [[ledger_node['node_id'], idx, ["day", "product", "backordered"]]],
                })
            if stock is not None:
                outcomes_list.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [prod_id],
                    "value": stock,
                    "src": [[ledger_node['node_id'], idx, ["day", "product", "stock"]]],
                })

    # Events outcomes
    event_nodes = _find_nodes(doc, scope_node, r'em\s+Events$')
    # gather all product ids for reference
    prod_ids = set()
    for e in entities(doc, scope):
        prod_ids.add(e['id'])
    for ev_node in event_nodes:
        lines = ev_node.get('lines', [])
        for lidx, line in enumerate(lines):
            # Extract day
            m = re.search(r'\bDay\s+(\d+)', line)
            day = int(m.group(1)) if m else None
            # Determine event kind
            kind = None
            if 'dispatch capacity reached' in line.lower():
                kind = 'capacity_reached'
            elif 'runs out of stock' in line.lower():
                kind = 'stock_run_out'
            elif 'fully backordered' in line.lower():
                kind = 'order_fully_backordered'
            elif 'backlog cleared' in line.lower():
                kind = 'backlog_cleared'
            elif 'shipped in full' in line.lower():
                kind = 'order_shipped_in_full'
            else:
                kind = 'event'

            # Find involved products
            inds = []
            for pid in prod_ids:
                if pid in line:
                    inds.append(pid)
            outcomes_list.append({
                "time": day,
                "kind": kind,
                "entities": inds,
                "value": None,
                "src": [[ev_node['node_id'], lidx]],
            })
    return outcomes_list

def params(doc, scope):
    """Return constants for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}
    txt_node = None
    # text node of the scope
    for n in children(doc, scope_node):
        if n['kind'] == 'text':
            txt_node = n
            break
    params_dict = {}
    if txt_node:
        # Extract daily dispatch capacity
        m = re.search(r'Daily dispatch capacity:\s*(\d+)\s*kg', txt_node['text'])
        if m:
            params_dict['daily_dispatch_capacity'] = int(m.group(1))
        # Extract plant id
        mpl = re.search(r'Plant\s+(\d+)', scope)
        if mpl:
            params_dict['plant_id'] = int(mpl.group(1))
    return params_dict

