from typing import List, Dict, Any, Tuple, Optional

# ------------------------------------------------------------------
# Helpers for navigating the doc structure
# ------------------------------------------------------------------
def node_by_title(doc: Dict, title: str) -> Optional[Dict]:
    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None

def children(doc: Dict, node: Dict) -> List[Dict]:
    ids = node.get("children", [])
    return [n for n in doc.get("nodes", []) if n["node_id"] in ids]

def table_rows(node: Dict) -> List[Tuple[int, Dict[str, str]]]:
    """Return list of (row_index, {col: value}) for a table node."""
    rows = []
