    if not scope_node:
        return []

    prod_rows = []
    prod_node = _find_child_with_title(scope_node, r”: Products$”)
    if prod_node:
        prod_rows = _parse_products_table(prod_node)
    else:
        # fall back to ledger
        ledger_node = _find_child_with_title(scope_node, r”: Daily ledger$”)
